package in.sqrock.railway.ui;

import in.sqrock.railway.dao.*;import in.sqrock.railway.model.*;
import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.time.LocalDate;import java.util.*;import java.util.List;

public class DashboardFrame extends JFrame {
    private final int userId; private final TrainDao trains=new TrainDao();private final BookingDao bookings=new BookingDao();
    private final JTextField source=new JTextField(12),destination=new JTextField(12);private final DefaultTableModel trainModel=new DefaultTableModel(new String[]{"ID","Train No.","Train Name","From","To","Departure","Arrival","Seats"},0){public boolean isCellEditable(int r,int c){return false;}};
    private final JTable trainTable=new JTable(trainModel);private final DefaultTableModel bookingModel=new DefaultTableModel(new String[]{"Booking ID","Train","Passenger","From","To","Date","Seat","Status"},0){public boolean isCellEditable(int r,int c){return false;}};private final JTable bookingTable=new JTable(bookingModel);
    public DashboardFrame(int userId,String username){this.userId=userId;setTitle("Railway Reservation System - "+username);setSize(1050,650);setLocationRelativeTo(null);setDefaultCloseOperation(EXIT_ON_CLOSE);build();loadHistory();}
    private void build(){JPanel root=new JPanel(new BorderLayout(10,10));root.setBorder(BorderFactory.createEmptyBorder(12,12,12,12));JLabel title=new JLabel("Railway Reservation Dashboard",SwingConstants.CENTER);title.setFont(new Font("Arial",Font.BOLD,23));root.add(title,BorderLayout.NORTH);
        JTabbedPane tabs=new JTabbedPane();JPanel search=new JPanel(new BorderLayout(8,8));JPanel form=new JPanel(new FlowLayout(FlowLayout.LEFT));form.add(new JLabel("From:"));form.add(source);form.add(new JLabel("To:"));form.add(destination);JButton find=new JButton("Search Trains"),book=new JButton("Book Selected Train");form.add(find);form.add(book);search.add(form,BorderLayout.NORTH);search.add(new JScrollPane(trainTable),BorderLayout.CENTER);find.addActionListener(e->searchTrains());book.addActionListener(e->bookSelected());tabs.addTab("Find & Book Trains",search);
        JPanel history=new JPanel(new BorderLayout(8,8));history.add(new JScrollPane(bookingTable),BorderLayout.CENTER);JPanel buttons=new JPanel(new FlowLayout(FlowLayout.LEFT));JButton refresh=new JButton("Refresh"),cancel=new JButton("Cancel Selected Booking");buttons.add(refresh);buttons.add(cancel);history.add(buttons,BorderLayout.SOUTH);refresh.addActionListener(e->loadHistory());cancel.addActionListener(e->cancelSelected());tabs.addTab("My Bookings",history);root.add(tabs,BorderLayout.CENTER);setContentPane(root);}
    private void searchTrains(){try{trainModel.setRowCount(0);for(Train t:trains.search(source.getText().trim(),destination.getText().trim()))trainModel.addRow(new Object[]{t.getId(),t.getNumber(),t.getName(),t.getSource(),t.getDestination(),t.getDeparture(),t.getArrival(),t.getAvailableSeats()});if(trainModel.getRowCount()==0)JOptionPane.showMessageDialog(this,"No trains found for this route.");}catch(Exception e){error(e);}}
    private void bookSelected(){int row=trainTable.getSelectedRow();if(row<0){JOptionPane.showMessageDialog(this,"Please select a train first.");return;}try{int trainId=(int)trainModel.getValueAt(row,0);Train selected=null;for(Train t:trains.search("", ""))if(t.getId()==trainId){selected=t;break;}if(selected==null)throw new Exception("Train details not found.");JTextField passenger=new JTextField(),age=new JTextField();JComboBox<String>gender=new JComboBox<>(new String[]{"Male","Female","Other"});JTextField date=new JTextField(LocalDate.now().plusDays(1).toString());Object[] fields={"Passenger name:",passenger,"Age:",age,"Gender:",gender,"Journey date (YYYY-MM-DD):",date};if(JOptionPane.showConfirmDialog(this,fields,"Passenger details",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;if(passenger.getText().trim().isEmpty())throw new Exception("Enter passenger name.");int a=Integer.parseInt(age.getText().trim());if(a<1||a>120)throw new Exception("Enter a valid age.");LocalDate d=LocalDate.parse(date.getText().trim());if(d.isBefore(LocalDate.now()))throw new Exception("Journey date cannot be in the past.");int seat=bookings.book(userId,selected,passenger.getText().trim(),a,(String)gender.getSelectedItem(),d.toString());JOptionPane.showMessageDialog(this,"Booking confirmed! Your seat number is "+seat);searchTrains();loadHistory();}catch(Exception e){error(e);}}
    private void loadHistory(){try{bookingModel.setRowCount(0);for(Booking b:bookings.history(userId))bookingModel.addRow(new Object[]{b.getId(),b.getTrainNumber()+" - "+b.getTrainName(),b.getPassenger(),b.getSource(),b.getDestination(),b.getJourneyDate(),b.getSeatNumber(),b.getStatus()});}catch(Exception e){error(e);}}
    private void cancelSelected(){int row=bookingTable.getSelectedRow();if(row<0){JOptionPane.showMessageDialog(this,"Select a booking first.");return;}if(!"CONFIRMED".equals(bookingModel.getValueAt(row,7))) {JOptionPane.showMessageDialog(this,"Only confirmed bookings can be cancelled.");return;}int id=(int)bookingModel.getValueAt(row,0);if(JOptionPane.showConfirmDialog(this,"Cancel this booking?","Confirm",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)try{bookings.cancel(id,userId);JOptionPane.showMessageDialog(this,"Booking cancelled.");loadHistory();}catch(Exception e){error(e);}}
    private void error(Exception e){JOptionPane.showMessageDialog(this,e.getMessage()==null?"Something went wrong.":e.getMessage(),"Error",JOptionPane.ERROR_MESSAGE);}
}
